    private fun q(ua: String, en: String, pl: String): GameQuestion {
        val a = AppLocale.t("🔥 БУЛО!", "🔥 I HAVE!", "🔥 BYŁO!")
        val b = AppLocale.t("😇 НІКОЛИ", "😇 NEVER", "😇 NIGDY")
        return GameQuestion("NEVER", AppLocale.t(ua, en, pl), a, b)
    }

